head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.MSG_TR_DOME = "작업이 정상적으로 처리되었습니다.";
scwin.MSG_TR_FAIL = "처리 중 오류가 발생하였습니다.";
scwin.fileYn = "N";
scwin.instYn = "N";
scwin.vBzProcsNo;
scwin.approvCd;
scwin.procsCd;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_Top);
        inf_find.hide();
        txb_fileseq.hide();
        const parentWin = $c.frame.path("../");
        scwin.vBzProcsNo = parentWin.clickBzProcsNo;
        await scwin.listSync();
        await scwin.fileList();
        await scwin.file5();
        scwin.setDataHeader();
        const parentFrameID = $c.stf.getQuery(frame.srcUrl, "frameID");
        if (parentFrameID.indexOf('STF60000') !== -1) {
            btn_acpt.hide();
            btn_Reject.hide();
            btn_Save.hide();
            btn_lineadd.hide();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07071.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_detail_OnLoadCompleted
 * @description dts_detail 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_detail_OnLoadCompleted = function(rowcount) {
    try {
        scwin.load();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07071.dts_detail_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await $c.win.alert(scwin.MSG_TR_FAIL);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07071.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        await $c.win.alert(scwin.MSG_TR_DOME);
        await scwin.listSync();
        await scwin.fileList();
        await scwin.file5();
        // 목록다시뿌림
        scwin.parentRefresh();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07071.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_File_OnFail
 * @description File On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_File_OnFail = async function() {
    try {
        await $c.win.alert(scwin.MSG_TR_FAIL);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07071.trs_File_OnFail" });
    }
};

/**
 * @method
 * @name trs_File_OnSuccess
 * @description File On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_File_OnSuccess = async function() {
    try {
        await scwin.file5();
        scwin.indexingElasitcSearch();
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07071.trs_File_OnSuccess" });
    }
};

/**
 * @method
 * @name btn_lineadd_onclick
 * @description btn_lineadd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_lineadd_onclick = function() {
    try {
        if (dts_file5.getCellData(1, "filename") === "") {
            dts_file5.insertRow();
            inf_find.open();
            if (inf_find.getValue() !== "") {
                dts_file5.setCellData(1, "fileInfo", inf_find.getValue());
                file_name.setValue(inf_find.getValue());
                txb_file5.setValue(inf_find.getValue());
            } else {
                dts_file5.removeRow(1);
                txb_file5.setValue("");
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07071.btn_lineadd_onclick" });
    }
};

/**
 * @method
 * @name dts_file5_OnLoadCompleted
 * @description dts_file5 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_file5_OnLoadCompleted = function(rowcount) {
    try {
        txb_fileseq.setValue(dts_file5.getCellData(1, "fileseq"));
        txb_file5.setValue(dts_file5.getCellData(1, "filename"));
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07071.dts_file5_OnLoadCompleted" });
    }
};

