/**
 * @method
 * @name grd_userlist_OnDblClick
 * @description grd_userlist 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_userlist_OnDblClick = async function(row, colid) {
    try {
        if (dts_fileList.getRowStatus(dts_fileList.getRowPosition()) === 0) {
            await scwin.filedown(dts_fileList.getCellData(row, "ATTACH_FILE_SEQ"), dts_fileList.getCellData(row, "PRTDEPO_ID"), dts_fileList.getCellData(row, "PRTDEPO_WITHD_APPL_SEQ"));
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07071.grd_userlist_OnDblClick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    const sbmOptions = {
        id : "sbm_dts_detail",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_detail=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

