/**
 * @method
 * @name fileSave
 * @description 파일저장
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fileSave = async function() {
    const pdid = dts_detail.getCellData(1, "PRTDEPO_ID");
    const id_seq = dts_detail.getCellData(1, "PRTDEPO_WITHD_APPL_SEQ");
    const type = "I";
    const filename = dts_file5.getCellData(1, "filename");
    if (filename === null || filename === "undefined" || filename.length === 0) vDispOfcdoc = true;
    trs_File.KeyName = "toinb_dataid4";
    const sbmOptions = {
        id : "sbm_trs_File",
        action : "/lstinvstg/PrtDepo.do",
        ref : "dts_file5",
        target : "trs_File=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name save
 * @description 바뀌는 상태
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    // 바뀌는 상태
    dts_detail.setCellData(1, "LST_APPROV_YN", scwin.approvCd);
    dts_detail.setCellData(1, "LIST_PROCS_STAT_CD", scwin.procsCd);
    dts_detail.setCellData(1, "INST_YN", scwin.instYn);
    trs_Save.KeyName = "toinb_dataid4";
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/lstinvstg/PrtDepo.do",
        ref : "dts_detail",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name load
 * @description 보호예수인출승인, 재보호예수가 없을 경우 승인시 보호예수T 에 update
 * @returns {void}
 * @hidden N
 */
scwin.load = function() {
    if (dts_detail.getCellData(1, "LST_APPROV_YN") === "2") {
        // 제출완료

        btn_acpt.show(""); // 접수
        btn_Save.hide(); // 인출승인 or 최종확인
        panel_1.hide(); // 파일저장
        scwin.approvCd = "3";

        /*if(dts_detail.NameString(1,"LIST_PROCS_STAT_CD") == "38"){
        	showObj(btn_Reject, false);//반려
        }else{
        	showObj(btn_Reject, true);//반려
        }*/
        btn_Reject.show(""); // 반려

        if (dts_detail.getCellData(1, "LIST_PROCS_STAT_CD") === "32" ||
            dts_detail.getCellData(1, "LIST_PROCS_STAT_CD") === "35" ||
            dts_detail.getCellData(1, "LIST_PROCS_STAT_CD") === "37") {
            scwin.procsCd = "33";
        } else {
            scwin.procsCd = dts_detail.getCellData(1, "LIST_PROCS_STAT_CD");
        }
    } else if (dts_detail.getCellData(1, "LST_APPROV_YN") === "3") {
        // 접수완료
        if (dts_detail.getCellData(1, "PRTDEPO_REOPN_YN") === "Y") {
            // 재보호예수가 있음 - 인출승인
            if (dts_detail.getCellData(1, "LIST_PROCS_STAT_CD") === "38") {
                btn_acpt.hide(); // 접수
                btn_Reject.hide(); // 반려
                btn_Save.show(""); // 인출승인 or 최종확인
                panel_1.hide(); // 파일저장
                btn_Save.setBackgroundImage("/img/btn_confirm.gif"); // 최종확인버튼
                scwin.approvCd = "9";
                scwin.procsCd = "39";
            }
            // 수정요청, 수정승인시
            else if (dts_detail.getCellData(1, "LIST_PROCS_STAT_CD") === "34" || dts_detail.getCellData(1, "LIST_PROCS_STAT_CD") === "35") {
                btn_acpt.hide();
                btn_Reject.hide();
                btn_Save.hide();
                panel_1.hide(); // 파일저장

            } else {
                btn_acpt.hide(); // 접수
                btn_Reject.hide(); // 반려
                btn_Save.show(""); // 인출승인 or 최종확인
                panel_1.show(""); // 파일저장
                btn_Save.setBackgroundImage("/img/btn_approval.gif"); // 인출승인 버튼
                scwin.approvCd = "8";
                scwin.procsCd = "38";
                scwin.instYn = "Y";
            }
        } else {
            // 재보호예수가 없음 - 최종확인
            btn_acpt.hide(); // 접수
            btn_Reject.hide(); // 반려
            btn_Save.show(""); // 인출승인 or 최종확인
            panel_1.show(""); // 파일저장
            btn_Save.setBackgroundImage("/img/btn_confirm.gif"); // 최종확인버튼
            scwin.approvCd = "9";
            scwin.procsCd = "39";
            scwin.instYn = "Y";
        }
    } else {
        btn_acpt.hide();
        btn_Reject.hide();
        btn_Save.hide();
        panel_1.hide(); // 파일저장

    }
};

/**
         * @method
         * @name check
         * @description check 처리
         * @returns {Promise<void>}
         * @hidden N
         */
scwin.check = async function() {
    if (txb_file5.getValue() === "") {
        await $c.win.alert("[처분승인공문]을 선택하세요.");
        txb_file5.focus();
        return false;
    }
};

/**
 * @method
 * @name filedown
 * @description 파일 다운로드
 * @param {*} attach_seq attach_seq
 * @param {String} prtdepo_Id prtdepo_Id
 * @param {*} prtdepo_seq prtdepo_seq
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.filedown = async function(attach_seq, prtdepo_Id, prtdepo_seq) {
    if (js_dep_cd === '2500' || js_dep_cd === '2520' || js_dep_cd === '2540' ||
        js_dep_cd === '3300' || js_dep_cd === '3320' || js_dep_cd === '3330' || js_dep_cd === '3350' ||
        js_dep_cd === '3E00' || js_dep_cd === '3E10' || js_dep_cd === '3E20' || js_dep_cd === '3E30' || js_dep_cd === '3E40' ||
        js_dep_cd === '3B00' || js_dep_cd === '3B30' || js_dep_cd === '2615' || js_dep_cd === '3G20') {
        location.href = "/filedownload.do?SCREN_ID=" + "ULDSTF07071.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&prtdepo_Id=" + prtdepo_Id + "&prtdepo_seq=" + prtdepo_seq + "&attach_seq=" + attach_seq + "&gubun=27";
    } else {
        await $c.win.alert('파일 열람 권한이 없습니다');
    }
};

/**
 * @method
 * @name setDataHeader
 * @description 파일첨부 head
 * @returns {void}
 * @hidden N
 */
scwin.setDataHeader = function() {

    // dts_file5.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인

};

/**
 * @method
 * @name saveType
 * @description save Type 처리
 * @param {*} jobType jobType
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.saveType = async function(jobType) {
    let rtn;
    let fileCheck = "N";

    // 접수
    if (jobType === "A") {
        // 접수
        rtn = confirm('의무보유주식의 처분을 접수하시겠습니까?');
    } else if (jobType === "R") {
        // 반려
        rtn = confirm('의무보유주식의 처분을 반려 하시겠습니까?');
        scwin.approvCd = "7";
        // procsCd = "37";
        if (dts_detail.getCellData(1, "LIST_PROCS_STAT_CD") === "38") {
            scwin.procsCd = "38";
        } else {
            scwin.procsCd = "37";
        }
    } else if (jobType === "S") {
        // 승인

        if (dts_detail.getCellData(1, "LIST_PROCS_STAT_CD") < "38") {
            scwin.fileYn = "Y";
            if (txb_file5.getValue() === "") {
                await $c.win.alert('처분승인공문을 첨부하여 주십시오.');
                return;
            }
        }
        if (scwin.approvCd === "9") {
            rtn = confirm('최종확인 하시겠습니까?');
            if (scwin.instYn === "Y") fileCheck = "Y"; // 재보호예수가 없을 경우 승인파일을 첨부하고 최종승인 됨.

        } else {
            rtn = confirm('처분승인 하시겠습니까?');
            fileCheck = "Y";
        }
    }
    if (rtn === 1) {
        if (fileCheck === "Y") {
            await scwin.fileSave();
        } else {
            await scwin.save();
        }
    }
};

/**
 * @method
 * @name parentRefresh
 * @description parent Refresh 처리
 * @returns {void}
 * @hidden N
 */
scwin.parentRefresh = function() {
    const fr_fn_list_sync = $c.frame.path("../").fn_list_sync;
    fr_fn_list_sync();
};

/**
 * @method
 * @name indexingElasitcSearch
 * @description indexing Elasitc Search 처리
 * @returns {void}
 * @hidden N
 */
scwin.indexingElasitcSearch = function() {
    prtdepo_withd_attach(dts_detail.getCellData(1, "PRTDEPO_ID"), dts_detail.getCellData(1, "PRTDEPO_WITHD_APPL_SEQ"));
};
